export class InvoiceService {
    renderHeader(inv: any): string {
        const name = inv.customer.name.trim().toUpperCase();
        const doc = inv.customer.document.replace(/[^0-9]/g, '');
        const city = inv.customer.address.city.trim();
        return `${name} ${doc} ${city}`;
    }

    renderTotals(inv: any): string {
        return String(inv.total);
    }

    renderFooter(inv: any): string {
        const name = inv.customer.name.trim().toUpperCase();
        const doc = inv.customer.document.replace(/[^0-9]/g, '');
        const city = inv.customer.address.city.trim();
        return `${name} ${doc} ${city}`;
    }
}

